package com.myassist.customer.ui;
import android.os.Bundle; import android.view.View; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.myassist.customer.model.Models; import com.myassist.customer.network.*; import org.json.JSONObject;
public class RequestDetailsActivity extends AppCompatActivity {int id; TextView status,body,error;Button cancel; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_request_details);id=getIntent().getIntExtra("request_id",-1);status=findViewById(R.id.tvStatus);body=findViewById(R.id.tvBody);error=findViewById(R.id.tvError);cancel=findViewById(R.id.btnCancel);cancel.setOnClickListener(v->cancel());load();} void load(){ApiService.run(ApiService.get("api/v1/customer/requests/"+id),Models.ServiceRequest::fromJson,new ApiService.Callback<Models.ServiceRequest>(){public void onSuccess(Models.ServiceRequest r){runOnUiThread(()->{status.setText(r.status);body.setText(r.serviceType+"\n\n"+r.description+"\n\nPickup: "+r.pickupAddress+"\nDestination: "+r.destinationAddress+"\nAssistant: "+(r.assistantName==null?"—":r.assistantName));cancel.setVisibility("PENDING".equals(r.status)?View.VISIBLE:View.GONE);});}public void onError(ApiClient.ApiException e){runOnUiThread(()->error.setText(e.userMessage));}});} void cancel(){ApiService.run(ApiService.post("api/v1/customer/requests/"+id+"/cancel",new JSONObject()),x->x,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject x){load();}public void onError(ApiClient.ApiException e){runOnUiThread(()->error.setText(e.userMessage));}});} }